import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BXzK3EA4.js";const r="/assets/77d45964a07b26a2.CzCeq-By.png",h=JSON.parse('{"title":"What to do if you are unable to access the desktop of a Windows Server 2012 system after uninstalling certain software","description":"","frontmatter":{"title":"What to do if you are unable to access the desktop of a Windows Server 2012 system after uninstalling certain software"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/windows/what-to-do-if-you-are-unable-to-access-the-desktop-of-a-windows-server-2012-syst.md","filePath":"operations-knowledge-base/operating-system/windows/what-to-do-if-you-are-unable-to-access-the-desktop-of-a-windows-server-2012-syst.md","lastUpdated":1794311093000}'),n={name:"operations-knowledge-base/operating-system/windows/what-to-do-if-you-are-unable-to-access-the-desktop-of-a-windows-server-2012-syst.md"};function i(l,e,p,d,u,c){return o(),s("div",null,[...e[0]||(e[0]=[a('<h4 id="_1-issue-description" tabindex="-1">1. Issue description <a class="header-anchor" href="#_1-issue-description" aria-label="Permalink to &quot;1. Issue description&quot;">​</a></h4><p>For Windows Server 2012 operating system, when installing certain applications that require .NET Framework 3.5, the built-in .NET Framework 4.5 version needs to be uninstalled. However, after uninstalling it, there might be issues such as a black screen and inability to access the system desktop. Only the Task Manager can be accessed in such cases.</p><h4 id="_2-possible-causes" tabindex="-1">2. Possible causes <a class="header-anchor" href="#_2-possible-causes" aria-label="Permalink to &quot;2. Possible causes&quot;">​</a></h4><p>After uninstalling .NET Framework 4.5, the system transitions from Full mode to Core mode, which does not enable the system desktop.</p><h4 id="_3-solution" tabindex="-1">3. solution <a class="header-anchor" href="#_3-solution" aria-label="Permalink to &quot;3. solution&quot;">​</a></h4><p>The recovery process involves transitioning from Core mode to Full mode. Follow the steps below:</p><ol><li><p>Log in to the server.</p></li><li><p>Open Task Manager.</p></li><li><p>Select &quot;File &gt; Run new task.&quot;</p></li></ol><p>The system opens the &quot;Create new task&quot; window.</p><p><img src="'+r+'" alt=""></p><ol start="4"><li><p>In the &quot;Open&quot; field, type &quot;cmd&quot; and press Enter.</p></li><li><p>In the opened command prompt window, execute the following command to transition the system from Core mode to Full mode:</p></li></ol><p>Dism /online /enable-feature /all /featurename:Server-Gui-Mgmt /featurename:Server-Gui-Shell /featurename:ServerCore-FullServer</p><ol start="6"><li>After approximately 10 minutes, the system will prompt for a restart. Enter &quot;Y&quot; in the command prompt to restart the system.</li></ol><p>After logging in again, the desktop should be displayed normally.</p>',13)])])}const f=t(n,[["render",i]]);export{h as __pageData,f as default};
